function allPermutations(arr) {
  const result = [];
  const used = new Array(arr.length).fill(false);
  function backtrack(current) {
    if (current.length === arr.length) { result.push([...current]); return; }
    for (let i = 0; i < arr.length; i++) {
      if (!used[i]) {
        used[i] = true; current.push(arr[i]);
        backtrack(current);
        current.pop(); used[i] = false;
      }
    }
  }
  backtrack([]);
  return result;
}
// allPermutations([1,1,2]) returns 6 entries, only 3 distinct.
